"""testdata/provenance.json (machine-readable) and testdata/LICENSES.md (rendered from it)."""

from __future__ import annotations

import json

from facelab.paths import TESTDATA_DIR

PROVENANCE_PATH = TESTDATA_DIR / "provenance.json"
LICENSES_PATH = TESTDATA_DIR / "LICENSES.md"

PORTRAITS_INTRO = """## Portraits (`images/`)

Source: Wikimedia Commons. At build time, each page was checked for the `{{PD-USGov-NASA}}` licence tag. That
tag means a photograph taken by a NASA employee as part of their official duties, which is in the public domain
in the United States (17 U.S.C. 105). Each original was verified against the SHA-1 Commons reported at curation
(2026-10-01), then downscaled to a long side of 1024 px (LANCZOS), re-encoded as JPEG quality 92 and stripped of
all metadata.

Public domain covers copyright only. NASA's media guidelines say that images of identifiable people (here,
astronauts) must not be used to imply endorsement. These files are internal test fixtures only. Never use them
in marketing, customer demos or published material.

| id | file | size | sha256 | licence | author | source page | original sha1 | note |
|---|---|---|---|---|---|---|---|---|
"""

DOCUMENTS_INTRO = """## Synthetic documents (`documents/`)

Generated by `python -m facelab testdata documents` from the portraits above. Every card is a fictitious
"SPECIMEN" layout drawn by the lab. It carries no real issuer's design, emblem, security feature or number
format, and all names and numbers are invented. Licence: same as the source portrait (public domain); the
synthetic layout is the Veriface authors' own work.

| id | file | size | sha256 | source portrait(s) | variant | expected |
|---|---|---|---|---|---|---|
"""


def load() -> dict:
    if PROVENANCE_PATH.exists():
        return json.loads(PROVENANCE_PATH.read_text(encoding="utf-8"))
    return {"portraits": [], "derived": [], "documents": []}


def all_images() -> dict[str, dict]:
    """id -> provenance row for every listed image (portraits, derived fixtures, documents)."""
    data = load()
    return {r["id"]: r for key in ("portraits", "derived", "documents") for r in data.get(key, [])}


def save(data: dict) -> None:
    PROVENANCE_PATH.write_text(json.dumps(data, indent=2, ensure_ascii=False) + "\n", encoding="utf-8", newline="\n")
    render_licenses(data)


def render_licenses(data: dict) -> None:
    out = ["# testdata provenance\n\n"]
    out.append(
        "Every file under `testdata/` is listed here. This file is rendered from `provenance.json` by "
        "`python -m facelab testdata ...`; do not edit it by hand. Golden outputs (`golden/`) are derived data "
        "computed from these images.\n\n"
    )
    out.append(PORTRAITS_INTRO)
    for r in data.get("portraits", []):
        out.append(
            f"| {r['id']} | `{r['file']}` | {r['size']} | `{r['sha256']}` | Public domain (PD-USGov-NASA) | "
            f"{r['author']} | {r['page']} | `{r['originalSha1']}` | {r['note']} |\n"
        )
    if data.get("derived"):
        out.append(
            "\n## Derived pose fixtures (`images/`)\n\nGeometric transforms of the portraits above, used to check "
            "pose sign conventions (testdata/golden/README.md). Licence: public domain, as the parent.\n\n"
            "| id | file | size | sha256 | parent | transform |\n|---|---|---|---|---|---|\n"
        )
        for r in data["derived"]:
            out.append(
                f"| {r['id']} | `{r['file']}` | {r['size']} | `{r['sha256']}` | {r['parent']} | {r['transform']} |\n"
            )
    if data.get("documents"):
        out.append("\n" + DOCUMENTS_INTRO)
        for r in data["documents"]:
            out.append(
                f"| {r['id']} | `{r['file']}` | {r['size']} | `{r['sha256']}` | {', '.join(r['sources']) or '-'} | "
                f"{r['variant']} | {r['expected']} |\n"
            )
    LICENSES_PATH.write_text("".join(out), encoding="utf-8", newline="\n")
